def solve():
    N, Q = map(int, input().split())
    boxes = [0] * N
    total_stones = 0

    def update(L, R, A, B):
        nonlocal total_stones
        for i in range(L - 1, R):
            stones = ((i - L + 2) * A) % B
            if boxes[i] != stones:
                total_stones -= boxes[i]
                boxes[i] = stones
                total_stones += stones

    for _ in range(Q):
        query = list(map(int, input().split()))
        if query[0] == 1:
            _, L, R, A, B = query
            update(L, R, A, B)
        else:
            _, L, R = query
            print(sum(boxes[L-1:R]))

if __name__ == "__main__":
